test('uploads a new avatar', async ({ page }) => {
  await page.goto('/settings/profile');
  await page.setInputFiles('input[type=file]', 'fixtures/me.png');
  await page.getByRole('button', { name: 'Upload' }).click();
  try {
    await expect(page.getByRole('img', { name: 'Your avatar' })).toHaveAttribute('src', /avatars\/new/);
  } catch (e) {
    console.log('avatar not updated yet');
  }
});
